# Obtener todos los gateways de WhatsApp gateways = env['mail.gateway'].search([('gateway_type', '=', 'whatsapp')])
if not gateways: raise UserError('No se encontraron gateways de WhatsApp configurados. Por favor, configure al menos un gateway antes de cargar las plantillas.')
created_count = 0 updated_count = 0
for gateway in gateways: # Diccionario para guardar las plantillas creadas y poder referenciarlas created_templates = {}
# Primera pasada: crear todas las plantillas for template_data in templates_data: # Buscar si ya existe existing = env['mail.whatsapp.template'].search([ ('name', '=', template_data['name']), ('gateway_id', '=', gateway.id), ('language', '=', template_data['language']), ], limit=1)
# Preparar datos de la plantilla template_vals = { 'name': template_data['name'], 'body': template_data['body'], 'category': template_data['category'], 'language': template_data['language'], 'model_id': template_data['model_id'], 'gateway_id': gateway.id, 'state': 'draft', }
if existing: # Actualizar plantilla existente existing.write(template_vals) template = existing updated_count += 1 else: # Crear nueva plantilla template = env['mail.whatsapp.template'].create(template_vals) created_count += 1
# Guardar la plantilla en el diccionario created_templates[template_data['name']] = template
# Segunda pasada: configurar variables for template_data in templates_data: template = created_templates[template_data['name']]
# Eliminar variables antiguas template.variable_ids.unlink()
# Crear variables for var_data in template_data['variables']: var_vals = { 'template_id': template.id, 'sequence': var_data['sequence'], 'variable_index': var_data['variable_index'], 'name': var_data['name'], 'field_name': var_data['field_name'], 'field_type': 'field', } # Agregar demo_value si existe if 'demo_value' in var_data: var_vals['demo_value'] = var_data['demo_value']
env['mail.whatsapp.template.variable'].create(var_vals)
# Mostrar resultado message = 'Plantillas cargadas correctamente:
- Creadas: %s
- Actualizadas: %s' % (created_count, updated_count) action = { 'type': 'ir.actions.client', 'tag': 'display_notification', 'params': { 'title': 'Plantillas Predefinidas', 'message': message, 'type': 'success', 'sticky': False, } }
